// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

/** What a compaction policy asks the applier to do next: nothing, merge a range of generations, or fold a prefix. */
final class AdjacencyCompactionPlan {

	enum Type {
		NONE,
		RANGE,
		FOLD
	}

	private static final AdjacencyCompactionPlan NONE = new AdjacencyCompactionPlan(Type.NONE, 0, 0, 0);

	private final Type type;
	private final int from;
	private final int toInclusive;
	private final int prefixCount;

	private AdjacencyCompactionPlan(Type type, int from, int toInclusive, int prefixCount) {
		this.type = type;
		this.from = from;
		this.toInclusive = toInclusive;
		this.prefixCount = prefixCount;
	}

	static AdjacencyCompactionPlan none() {
		return NONE;
	}

	static AdjacencyCompactionPlan range(int from, int toInclusive) {
		if (from < 0 || toInclusive <= from) {
			throw new IllegalArgumentException("a merge range needs at least two generations: [" + from + ", "
					+ toInclusive + "]");
		}
		return new AdjacencyCompactionPlan(Type.RANGE, from, toInclusive, 0);
	}

	static AdjacencyCompactionPlan fold(int prefixCount) {
		if (prefixCount <= 0) {
			throw new IllegalArgumentException("a fold needs at least one generation: " + prefixCount);
		}
		return new AdjacencyCompactionPlan(Type.FOLD, 0, 0, prefixCount);
	}

	Type type() {
		return type;
	}

	int from() {
		return from;
	}

	int toInclusive() {
		return toInclusive;
	}

	int prefixCount() {
		return prefixCount;
	}

	@Override
	public String toString() {
		switch (type) {
		case RANGE:
			return "merge[" + from + ".." + toInclusive + "]";
		case FOLD:
			return "fold[" + prefixCount + "]";
		default:
			return "none";
		}
	}
}
